//! The guest struct offsets in `src/boopsi_ids.rs` against the m68k compiler's: `tests/guest/boopsi_offsets.txt` is
//! generated by `tests/guest/boopsi_offsets.sh` (m68k-linux-gnu-gcc -m68020 -mno-align-int over the AROS field lists).
use amiga68k_engine::boopsi_ids as b;

const TABLE: &str = include_str!("guest/boopsi_offsets.txt");

fn ours() -> Vec<(&'static str, u32)> {
    vec![
        ("CL_SIZE", b::CL_SIZE), ("CL_H_ENTRY", b::CL_H_ENTRY), ("CL_H_DATA", b::CL_H_DATA), ("CL_SUPER", b::CL_SUPER), ("CL_ID", b::CL_ID),
        ("CL_INST_OFFSET", b::CL_INST_OFFSET), ("CL_INST_SIZE", b::CL_INST_SIZE), ("CL_USER_DATA", b::CL_USER_DATA),
        ("CL_SUBCLASS_COUNT", b::CL_SUBCLASS_COUNT), ("CL_OBJECT_COUNT", b::CL_OBJECT_COUNT), ("CL_FLAGS", b::CL_FLAGS), ("CL_OBJECT_SIZE", b::CL_OBJECT_SIZE),
        ("OBJ_HEADER", b::OBJ_HEADER), ("OBJ_CLASS", b::OBJ_CLASS),
        ("GAD_NEXT", b::GAD_NEXT), ("GAD_LEFT", b::GAD_LEFT), ("GAD_TOP", b::GAD_TOP), ("GAD_WIDTH", b::GAD_WIDTH), ("GAD_HEIGHT", b::GAD_HEIGHT),
        ("GAD_FLAGS", b::GAD_FLAGS), ("GAD_ACTIVATION", b::GAD_ACTIVATION), ("GAD_TYPE", b::GAD_TYPE), ("GAD_RENDER", b::GAD_RENDER),
        ("GAD_SELECT", b::GAD_SELECT), ("GAD_TEXT", b::GAD_TEXT), ("GAD_MUTUAL", b::GAD_MUTUAL), ("GAD_SPECIAL", b::GAD_SPECIAL),
        ("GAD_ID", b::GAD_ID), ("GAD_USER", b::GAD_USER), ("EGAD_MORE_FLAGS", b::EGAD_MORE_FLAGS), ("EGAD_BOUNDS", b::EGAD_BOUNDS),
        ("GDATA_SIZE", b::GDATA_SIZE), ("GDATA_IC", b::GDATA_IC), ("IC_TARGET", b::IC_TARGET), ("IC_MAPPING", b::IC_MAPPING),
        ("IMG_SIZE", b::IMG_SIZE), ("IMG_LEFT", b::IMG_LEFT), ("IMG_TOP", b::IMG_TOP), ("IMG_WIDTH", b::IMG_WIDTH), ("IMG_HEIGHT", b::IMG_HEIGHT),
        ("IMG_DEPTH", b::IMG_DEPTH), ("IMG_DATA", b::IMG_DATA), ("IMG_PLANE_PICK", b::IMG_PLANE_PICK), ("IMG_PLANE_ONOFF", b::IMG_PLANE_ONOFF),
        ("GI_SIZE", b::GI_SIZE), ("GI_SCREEN", b::GI_SCREEN), ("GI_WINDOW", b::GI_WINDOW), ("GI_RASTPORT", b::GI_RASTPORT), ("GI_LAYER", b::GI_LAYER),
        ("GI_DOMAIN", b::GI_DOMAIN), ("GI_PENS", b::GI_PENS), ("GI_DRINFO", b::GI_DRINFO), ("OPSET_GINFO", b::OPSET_GINFO),
        ("GPR_SIZE", b::GPR_SIZE), ("GPR_RPORT", b::GPR_RPORT), ("GPR_REDRAW", b::GPR_REDRAW), ("GPHT_SIZE", b::GPHT_SIZE), ("GPHT_MOUSE", b::GPHT_MOUSE),
        ("GPI_SIZE", b::GPI_SIZE), ("GPI_IEVENT", b::GPI_IEVENT), ("GPI_TERMINATION", b::GPI_TERMINATION), ("GPI_MOUSE", b::GPI_MOUSE),
        ("GPGI_SIZE", b::GPGI_SIZE), ("GPGI_ABORT", b::GPGI_ABORT), ("GPL_SIZE", b::GPL_SIZE), ("GPL_INITIAL", b::GPL_INITIAL),
    ]
}

#[test]
fn every_constant_equals_the_compilers_offset() {
    let table: Vec<(&str, u32)> = TABLE.lines().map(|l| { let (n, v) = l.split_once(' ').unwrap(); (n, v.trim().parse().unwrap()) }).collect();
    for (name, mine) in ours() {
        let (_, want) = table.iter().find(|(n, _)| *n == name).unwrap_or_else(|| panic!("{name} is not in boopsi_offsets.txt"));
        assert_eq!(mine, *want, "{name}: boopsi_ids.rs says {mine}, m68k gcc says {want}");
    }
}

#[test]
fn the_comparison_can_fail() {
    let mut o = ours();
    o[0].1 += 1;
    let want: u32 = TABLE.lines().find(|l| l.starts_with("CL_SIZE ")).unwrap().split(' ').nth(1).unwrap().parse().unwrap();
    assert_ne!(o[0].1, want, "negative control: a drifted constant differs");
}
